parameters.content:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "r");
    if (!f) {
        perror("fopen");
        return 1;
    }

    char line[4096];
    int total = 0, kept = 0;

    // Skip header
    if (!fgets(line, sizeof(line), f)) {
        fprintf(stderr, "Empty file\n");
        return 1;
    }

    while (fgets(line, sizeof(line), f)) {
        total++;
        // Parse comma-separated: field 8 (0-indexed: 7) is MethylationPercentage
        char *tok = strtok(line, ",");
        int field = 0;
        double meth = -1;
        while (tok) {
            if (field == 7) {
                meth = atof(tok);
                break;
            }
            tok = strtok(NULL, ",");
            field++;
        }
        if (meth > 90.0 || meth < 10.0) {
            kept++;
        }
    }
    fclose(f);

    int removed = total - kept;
    printf("Total: %d\nKept: %d\nRemoved: %d\n", total, kept, removed);
    return 0;
}

